import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const y=JSON.parse('{"title":"TV Theme","description":"","frontmatter":{},"headers":[],"relativePath":"demos/TV_THEME.md","filePath":"demos/TV_THEME.md"}'),o={name:"demos/TV_THEME.md"};function h(s,e,i,l,d,m){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="tv-theme" tabindex="-1">TV Theme <a class="header-anchor" href="#tv-theme" aria-label="Permalink to &quot;TV Theme&quot;">​</a></h1><p>The demo songs in the TV theme style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#aunt_clara">Light-Jazz Sitcom Theme</a>: <code>aunt_clara.yml</code></li><li><a href="#come_on_down">Game-Show Theme</a>: <code>come_on_down.yml</code></li><li><a href="#eats_cats">Slap-Bass Sitcom Theme</a>: <code>eats_cats.yml</code></li><li><a href="#forgot_your_name">Sitcom Theme</a>: <code>forgot_your_name.yml</code></li><li><a href="#meeting_the_eye">Hard-Rock Cartoon Theme</a>: <code>meeting_the_eye.yml</code></li><li><a href="#mysterious_spooky">Creepy Harpsichord Theme</a>: <code>mysterious_spooky.yml</code></li><li><a href="#not_painless">Wistful Guitar Theme</a>: <code>not_painless.yml</code></li><li><a href="#phoenix_foundation">Action-Show Theme</a>: <code>phoenix_foundation.yml</code></li><li><a href="#sax_reindeer">Novelty Saxophone Romp</a>: <code>sax_reindeer.yml</code></li><li><a href="#spy_hunting">Spy Theme</a>: <code>spy_hunting.yml</code></li><li><a href="#three_hour_tour">Sea-Shanty Sitcom Theme</a>: <code>three_hour_tour.yml</code></li><li><a href="#tropical_51">Big-Band Police Theme</a>: <code>tropical_51.yml</code></li><li><a href="#uk_butler">Ragtime Sitcom Theme</a>: <code>uk_butler.yml</code></li></ul><p><a id="aunt_clara"></a></p><h2 id="light-jazz-sitcom-theme-aunt-clara-yml" tabindex="-1">Light-Jazz Sitcom Theme: <code>aunt_clara.yml</code> <a class="header-anchor" href="#light-jazz-sitcom-theme-aunt-clara-yml" aria-label="Permalink to &quot;Light-Jazz Sitcom Theme: `aunt_clara.yml`&quot;">​</a></h2><p>A twinkling light-jazz sitcom theme of the sixties in the manner of the Bewitched theme (Howard Greenfield and Jack Keller), with a tune of its own. A swinging ride, a walking bass and plucked strings; a vibraphone with a skipping tune on I vi ii V, a celesta sparkling after each phrase; a bridge through four dominant chords; choruses for a muted trumpet and a flute.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/tv_theme/aunt_clara.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/tv_theme/aunt_clara.yml</code></a> · Bb major · 138 BPM · 1:03 · 4 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">grooves</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../GROOVES">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="come_on_down"></a></p><h2 id="game-show-theme-come-on-down-yml" tabindex="-1">Game-Show Theme: <code>come_on_down.yml</code> <a class="header-anchor" href="#game-show-theme-come-on-down-yml" aria-label="Permalink to &quot;Game-Show Theme: `come_on_down.yml`&quot;">​</a></h2><p>A bright seventies game-show theme in the manner of The Price Is Right theme (Edd Kalehoff), with a tune of its own. A brass section and a synthesizer in unison on a leaping tune, a clavinet chopping sixteenths, funky bass octaves and a busy drum kit with a tambourine; a bridge, a flute chorus and a drum break.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/tv_theme/come_on_down.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/tv_theme/come_on_down.yml</code></a> · G major · 126 BPM · 1:09 · 4 scenes · 10 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="eats_cats"></a></p><h2 id="slap-bass-sitcom-theme-eats-cats-yml" tabindex="-1">Slap-Bass Sitcom Theme: <code>eats_cats.yml</code> <a class="header-anchor" href="#slap-bass-sitcom-theme-eats-cats-yml" aria-label="Permalink to &quot;Slap-Bass Sitcom Theme: `eats_cats.yml`&quot;">​</a></h2><p>A bouncing mid-eighties sitcom instrumental in the manner of the ALF theme (Alf Clausen), with a tune of its own. A slap bass alone, then a drum machine and an electric piano; a syncopated synth brass tune over I, vi and the flat seventh; a second strain and a sax chorus.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/tv_theme/eats_cats.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/tv_theme/eats_cats.yml</code></a> · D major · 128 BPM · 1:08 · 4 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="forgot_your_name"></a></p><h2 id="sitcom-theme-forgot-your-name-yml" tabindex="-1">Sitcom Theme: <code>forgot_your_name.yml</code> <a class="header-anchor" href="#sitcom-theme-forgot-your-name-yml" aria-label="Permalink to &quot;Sitcom Theme: `forgot_your_name.yml`&quot;">​</a></h2><p>A warm piano sitcom theme in the manner of Cheers (Gary Portnoy), with a melody of its own. A piano alone under a quiet verse on I and V, then the band, strings and a choir for a chorus that opens out on I bVII IV V; a bridge, and the piano alone to end.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/tv_theme/forgot_your_name.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/tv_theme/forgot_your_name.yml</code></a> · Eb major · 92 BPM · 1:03 · 4 scenes · 11 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="meeting_the_eye"></a></p><h2 id="hard-rock-cartoon-theme-meeting-the-eye-yml" tabindex="-1">Hard-Rock Cartoon Theme: <code>meeting_the_eye.yml</code> <a class="header-anchor" href="#hard-rock-cartoon-theme-meeting-the-eye-yml" aria-label="Permalink to &quot;Hard-Rock Cartoon Theme: `meeting_the_eye.yml`&quot;">​</a></h2><p>A one-minute hard-rock cartoon theme of the mid eighties in the manner of the theme of The Transformers (Ford Kinder and Anne Bryant), with a tune of its own. The band plays the slogan&#39;s rhythm alone, then the voices shout it; a chorus on i VII i V and VI VII i that a robot voice answers; one low verse; a drum break with the robot alone; the chorus and the slogan again.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/tv_theme/meeting_the_eye.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/tv_theme/meeting_the_eye.yml</code></a> · D minor · 138 BPM · 1:06 · 7 scenes · 11 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="mysterious_spooky"></a></p><h2 id="creepy-harpsichord-theme-mysterious-spooky-yml" tabindex="-1">Creepy Harpsichord Theme: <code>mysterious_spooky.yml</code> <a class="header-anchor" href="#creepy-harpsichord-theme-mysterious-spooky-yml" aria-label="Permalink to &quot;Creepy Harpsichord Theme: `mysterious_spooky.yml`&quot;">​</a></h2><p>A creepy, kooky harpsichord theme in the manner of The Addams Family (Vic Mizzy), with a tune of its own. A short, low harpsichord figure answered by two snaps, played on one chord and then a step higher; a bouncing tune over a tuba, with a dominant chord on II; a reed organ takes the tune in the middle.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/tv_theme/mysterious_spooky.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/tv_theme/mysterious_spooky.yml</code></a> · G major · 132 BPM · 1:05 · 4 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="not_painless"></a></p><h2 id="wistful-guitar-theme-not-painless-yml" tabindex="-1">Wistful Guitar Theme: <code>not_painless.yml</code> <a class="header-anchor" href="#wistful-guitar-theme-not-painless-yml" aria-label="Permalink to &quot;Wistful Guitar Theme: `not_painless.yml`&quot;">​</a></h2><p>A gentle, wistful guitar theme in the manner of M<em>A</em>S*H (Johnny Mandel), with a melody of its own. A verse on iv VII III i, twice, a progression moving one bar of picking; a refrain on VI VII v i, iv VII i; the tune&#39;s lines each answered; about a minute, as a theme runs.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/tv_theme/not_painless.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/tv_theme/not_painless.yml</code></a> · G minor · 90 BPM · 1:04 · 4 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">guitarify</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/GUITARIFY">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="phoenix_foundation"></a></p><h2 id="action-show-theme-phoenix-foundation-yml" tabindex="-1">Action-Show Theme: <code>phoenix_foundation.yml</code> <a class="header-anchor" href="#action-show-theme-phoenix-foundation-yml" aria-label="Permalink to &quot;Action-Show Theme: `phoenix_foundation.yml`&quot;">​</a></h2><p>A mid-eighties action-show theme in the manner of MacGyver (Randy Edelman), with a melody of its own. Four bars of pulse and hits, the tune on I, IV and V, the tune again with a second brass answering, a climbing middle part and the tune&#39;s first half to close, in about a minute.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/tv_theme/phoenix_foundation.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/tv_theme/phoenix_foundation.yml</code></a> · A major · 130 BPM · 0:59 · 5 scenes · 10 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="sax_reindeer"></a></p><h2 id="novelty-saxophone-romp-sax-reindeer-yml" tabindex="-1">Novelty Saxophone Romp: <code>sax_reindeer.yml</code> <a class="header-anchor" href="#novelty-saxophone-romp-sax-reindeer-yml" aria-label="Permalink to &quot;Novelty Saxophone Romp: `sax_reindeer.yml`&quot;">​</a></h2><p>A breakneck novelty saxophone romp in the manner of Yakety Sax (Boots Randolph), with runs of its own. A tenor sax running in sixteenths over a country two-beat, bass on one and three and the piano and guitar on the offbeats, a train beat on the snare; a second part that wails on long notes over IV, I and a dominant II; the last time a step higher.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/tv_theme/sax_reindeer.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/tv_theme/sax_reindeer.yml</code></a> · Bb major · 144 BPM · 1:00 · 4 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">key changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="spy_hunting"></a></p><h2 id="spy-theme-spy-hunting-yml" tabindex="-1">Spy Theme: <code>spy_hunting.yml</code> <a class="header-anchor" href="#spy-theme-spy-hunting-yml" aria-label="Permalink to &quot;Spy Theme: `spy_hunting.yml`&quot;">​</a></h2><p>A late fifties spy-jazz theme in the manner of Peter Gunn (Henry Mancini), with a riff and a tune of its own. One bar of low eighths on a twangy guitar, a piano and a bass, on one chord, that never stops; brass chords that swell over it; a head in long blue notes and a wailing tenor sax solo; once, the riff moves to iv and back.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/tv_theme/spy_hunting.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/tv_theme/spy_hunting.yml</code></a> · G minor · 120 BPM · 0:56 · 3 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="three_hour_tour"></a></p><h2 id="sea-shanty-sitcom-theme-three-hour-tour-yml" tabindex="-1">Sea-Shanty Sitcom Theme: <code>three_hour_tour.yml</code> <a class="header-anchor" href="#sea-shanty-sitcom-theme-three-hour-tour-yml" aria-label="Permalink to &quot;Sea-Shanty Sitcom Theme: `three_hour_tour.yml`&quot;">​</a></h2><p>A sea-shanty sitcom theme of the sixties in the manner of The Ballad of Gilligan&#39;s Isle (Sherwood Schwartz and George Wyle), with tunes of its own. A shanty in minor on i and VII, strummed by a Guitarify on an acoustic guitar; a refrain in which a line from the singer is answered by the men; a turn of four bars on VI, III, iv and V; each verse a half step higher, from D minor to E minor, in about a minute.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/tv_theme/three_hour_tour.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/tv_theme/three_hour_tour.yml</code></a> · D minor · 132 BPM · 1:05 · 6 scenes · 9 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">guitarify</th><th style="text-align:center;">ties</th><th style="text-align:center;">key changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/GUITARIFY">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="tropical_51"></a></p><h2 id="big-band-police-theme-tropical-51-yml" tabindex="-1">Big-Band Police Theme: <code>tropical_51.yml</code> <a class="header-anchor" href="#big-band-police-theme-tropical-51-yml" aria-label="Permalink to &quot;Big-Band Police Theme: `tropical_51.yml`&quot;">​</a></h2><p>A big-band police-show theme in the manner of Hawaii Five-0 (Morton Stevens), with a fanfare of its own. Tom-toms and timpani open, then a trumpet fanfare in bold leaps over a driving bass, tambourine and brass on the offbeats, the chords falling i VII VI to a major V; trombones answer; and the whole thing rises a step, twice.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/tv_theme/tropical_51.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/tv_theme/tropical_51.yml</code></a> · A minor · 150 BPM · 1:04 · 5 scenes · 12 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">key changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="uk_butler"></a></p><h2 id="ragtime-sitcom-theme-uk-butler-yml" tabindex="-1">Ragtime Sitcom Theme: <code>uk_butler.yml</code> <a class="header-anchor" href="#ragtime-sitcom-theme-uk-butler-yml" aria-label="Permalink to &quot;Ragtime Sitcom Theme: `uk_butler.yml`&quot;">​</a></h2><p>A saloon-piano ragtime sitcom theme in the manner of the Mr. Belvedere theme (Judy Hart-Angelo and Gary Portnoy, as Leon Redbone sang it), with a tune of its own. A honky-tonk piano opens alone with a rag figure over a low note and a chord by turns; a lazy tune over ragtime chords, the piano filling each gap; the piano takes a chorus in octaves; a scatted tag on a muted trumpet.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/tv_theme/uk_butler.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/tv_theme/uk_butler.yml</code></a> · D major · 120 BPM · 1:12 · 4 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">grooves</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../GROOVES">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table>',68)])])}const g=t(o,[["render",h]]);export{y as __pageData,g as default};
